package com.opensocket.aievent.core.issuetracking.application.recovery;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.HexFormat;import java.util.UUID;import org.springframework.stereotype.Service;import com.opensocket.aievent.core.issuetracking.recovery.*;
@Service public class ProjectionRecoveryEventLedger { private final ProjectionRecoveryRepository repo; public ProjectionRecoveryEventLedger(ProjectionRecoveryRepository repo){this.repo=repo;} public ProjectionRecoveryEvent append(String tenant,String type,String id,ProjectionRecoveryEventType eventType,String actor,String reason,String metadata,String correlation){String previous=repo.latestEvent(tenant,type,id).map(ProjectionRecoveryEvent::eventHash).orElse("");OffsetDateTime now=OffsetDateTime.now(ZoneOffset.UTC);String eventId="pre-"+UUID.randomUUID();String hash=hash(previous+"|"+tenant+"|"+type+"|"+id+"|"+eventType+"|"+reason+"|"+metadata+"|"+now);return repo.appendEvent(new ProjectionRecoveryEvent(tenant,eventId,type,id,eventType,actor,reason,metadata==null?"{}":metadata,previous,hash,now,correlation));}private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
